  if(result.error){el.innerHTML=`<div class="live-search-result-message"><strong>Não encontrei ${escapeHtml(result.query||'este ativo')}.</strong><br>${escapeHtml(result.error)}</div>`;return;}
  const item=result.item; const change=item?.changePct==null?null:Number(item.changePct); const hasChange=change!=null&&Number.isFinite(change);
  el.innerHTML=`<div class="live-search-result-row"><div><strong>${escapeHtml(item?.label||item?.symbol||result.query)}</strong><small>${escapeHtml(item?.symbol||'')} · ${escapeHtml(liveGroupLabel(item?.group))} · ${escapeHtml(item?.source||'fonte conectada')}</small></div><div class="live-search-result-price">${formatLiveValue(item)}</div><div class="live-search-result-status ${hasChange?(change>=0?'positive':'negative'):''}">${hasChange?`${change>=0?'+':''}${fmtPct(change)}`:(item?.asOf?fmtDateTime(item.asOf):'cotação')}</div></div>`;
