  if(item.format==='currency')return money.format(v);
  if(item.format==='number')return number.format(v);
  if(item.format==='percent')return `${pct.format(v)}%`;
  if(item.format==='index')return new Intl.NumberFormat('pt-BR',{maximumFractionDigits:0}).format(v);
