  for(const w of state.watchlist.filter(x=>x.changeAlertTriggered))rows.push({id:`watch-change:${w.id||w.symbol}:${day}`,severity:'warning',category:'watchlist',symbol:w.symbol,title:`${w.symbol}: oscilação acima do limite`,text:`Variação observada ${w.marketChangePct==null?'—':fmtPct(w.marketChangePct)} versus limite pessoal de ${fmtPct(w.alertChangePct)}.`,source:'Watchlist',observedAt:w.marketPriceAt||now.toISOString()});
