  const events=[...tx.map(x=>({date:x.tradeDate,title:TYPE_LABELS[x.kind]||x.kind,sub:x.symbol||x.notes||'Fluxo de caixa',value:x.kind==='BUY'||x.kind==='SELL'?(Number(x.quantity)||0)*(Number(x.unitPrice)||0):(Number(x.unitPrice)||0),kind:x.kind})),...inc.map(x=>({date:x.paymentDate,title:INCOME_LABELS[x.incomeType]||x.incomeType,sub:x.symbol||x.notes||'Provento',value:Number(x.netAmount ?? ((x.grossAmount||0)-(x.taxAmount||0)))||0,kind:'INCOME'}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)));
  $('closingActivityBadge').textContent=`${events.length} registro${events.length===1?'':'s'}`;$('closingActivity').innerHTML=events.length?events.map(e=>`<div class="closing-event"><time>${fmtDate(e.date)}</time><div><strong>${escapeHtml(e.title)}</strong><small>${escapeHtml(e.sub||'')}</small></div><div class="event-value ${e.kind==='WITHDRAWAL'||e.kind==='BUY'?'negative':'positive'}">${money.format(e.value||0)}</div></div>`).join(''):'<div class="closing-empty">Nenhuma movimentação ou provento registrado neste mês.</div>';
  const targetTotal=state.targets.reduce((s,x)=>s+(Number(x.targetPct)||0),0), missingQuotes=state.assets.filter(a=>a.autoQuote&&a.marketPrice==null).length, noAvg=state.assets.filter(a=>(Number(a.averagePrice)||0)<=0).length, stale=state.assets.filter(a=>a.autoQuote&&a.marketPriceAt&&(Date.now()-new Date(a.marketPriceAt).getTime())>60*60*1000).length;
