  const score=Math.round(checks.filter(x=>x.ok).length/checks.length*100);$('closingDataScore').textContent=`${score}%`;$('dataHealthList').innerHTML=checks.map(x=>`<div class="health-row ${x.ok?'':x.bad?'bad':'warn'}"><i class="health-dot"></i><div><strong>${escapeHtml(x.label)}</strong><small>${escapeHtml(x.detail)}</small></div><span class="health-state">${x.ok?'ok':'revisar'}</span></div>`).join('');
