  const close=closingForMonth(month);$('closingStatus').value=close.status||'OPEN';$('closingNotes').value=close.notes||'';$('closingStatusBadge').textContent=(close.status||'OPEN')==='CLOSED'?'fechado':'aberto';
  renderGoalPace();
