function renderAssetDossier(){const el=$('assetDossier');if(!el)return;const id=Number($('dossierAsset')?.value),a=state.assets.find(x=>x.id===id)||state.assets[0];if(!a){el.innerHTML='<div class="closing-empty">Cadastre um ativo para abrir o dossiê.</div>';return;}const price=effectiveAssetPrice(a),value=(Number(a.quantity)||0)*price,invested=(Number(a.quantity)||0)*(Number(a.averagePrice)||0),result=value-invested,resultPct=invested?result/invested*100:0;const tx=state.transactions.filter(x=>x.symbol===a.symbol).slice(0,5),inc=state.income.filter(x=>x.symbol===a.symbol).slice(0,5);el.innerHTML=`<div class="dossier-hero"><div><h5>${escapeHtml(a.symbol)}</h5><p>${escapeHtml(a.name)} · ${escapeHtml(a.assetClass)}</p></div><div class="dossier-value"><strong>${money.format(value)}</strong><small>${number.format(a.quantity||0)} un. · ${money.format(price)}</small></div></div><div class="dossier-stats"><div class="dossier-stat"><span>Preço médio</span><strong>${money.format(a.averagePrice||0)}</strong><small>custo informado</small></div><div class="dossier-stat"><span>Resultado</span><strong class="${result>=0?'positive':'negative'}">${money.format(result)}</strong><small>${fmtPct(resultPct)}</small></div><div class="dossier-stat"><span>Dia</span><strong class="${(a.marketChangePct||0)>=0?'positive':'negative'}">${fmtPct(a.marketChangePct||0)}</strong><small>${a.marketPriceAt?fmtDateTime(a.marketPriceAt):'sem cotação'}</small></div><div class="dossier-stat"><span>Meta individual</span><strong>${fmtPct(a.targetPct||0)}</strong><small>${escapeHtml(a.notes||'sem observações')}</small></div></div><div class="dossier-timeline">${[...tx.map(x=>({date:x.tradeDate,label:TYPE_LABELS[x.kind]||x.kind,value:(x.kind==='BUY'||x.kind==='SELL')?(Number(x.quantity)||0)*(Number(x.unitPrice)||0):(Number(x.unitPrice)||0)})),...inc.map(x=>({date:x.paymentDate,label:INCOME_LABELS[x.incomeType]||x.incomeType,value:Number(x.netAmount ?? ((x.grossAmount||0)-(x.taxAmount||0)))||0}))].sort((x,y)=>String(y.date).localeCompare(String(x.date))).slice(0,6).map(x=>`<div class="dossier-line"><span>${fmtDate(x.date)} · ${escapeHtml(x.label)}</span><strong>${money.format(x.value||0)}</strong></div>`).join('')||'<div class="closing-empty">Ainda não há histórico registrado para este ativo.</div>'}</div>`;}
function renderGoalPace(){const el=$('goalPaceList');if(!el)return;const now=new Date();const rows=state.financialGoals.filter(g=>(Number(g.targetAmount)||0)>0).map(g=>{const remaining=Math.max(0,(Number(g.targetAmount)||0)-(Number(g.currentAmount)||0));let months=null;if(g.targetDate){const d=new Date(`${String(g.targetDate).slice(0,10)}T00:00:00`);months=Math.max(1,(d.getFullYear()-now.getFullYear())*12+(d.getMonth()-now.getMonth()));}return {...g,remaining,months,monthly:months?remaining/months:null};});el.innerHTML=rows.length?rows.map(g=>`<div class="goal-pace-row"><div><strong>${escapeHtml(g.title)}</strong><small>${g.targetDate?`até ${fmtDate(g.targetDate)} · ${g.months} mês(es) aproximados`:'sem prazo definido'}</small></div><div class="goal-pace-value"><strong>${money.format(g.remaining)}</strong><small>saldo restante</small></div><div class="goal-pace-value"><strong>${g.monthly==null?'—':money.format(g.monthly)}</strong><small>${g.monthly==null?'defina uma data':'por mês, sem retorno'}</small></div></div>`).join(''):'<div class="closing-empty">Cadastre metas em Vida financeira para acompanhar o ritmo aqui.</div>';}
async function saveMonthlyClosing(){const month=closingMonthValue(),status=$('closingStatus').value,notes=$('closingNotes').value;const btn=$('saveClosingButton');setBusy(btn,true,'Salvando…');try{if(state.preview){const row={month,status,notes,updatedAt:new Date().toISOString()};state.monthlyClosings=[row,...state.monthlyClosings.filter(x=>x.month!==month)];savePreviewFinance();}else{const data=await api('/api/monthly-closing',{method:'PUT',body:JSON.stringify({month,status,notes})});state.monthlyClosings=[data.closing,...state.monthlyClosings.filter(x=>x.month!==month)];}renderClosing();toast('Fechamento mensal salvo.');}catch(e){toast(e.message)}finally{setBusy(btn,false);}}
function downloadClosingCsv(){const month=closingMonthValue(),tx=state.transactions.filter(x=>String(x.tradeDate||'').slice(0,7)===month),inc=state.income.filter(x=>String(x.paymentDate||'').slice(0,7)===month),close=closingForMonth(month);const rows=[['Tipo','Data','Ativo/Descrição','Valor'],...tx.map(x=>[TYPE_LABELS[x.kind]||x.kind,x.tradeDate,x.symbol||x.notes||'',x.kind==='BUY'||x.kind==='SELL'?(Number(x.quantity)||0)*(Number(x.unitPrice)||0):(Number(x.unitPrice)||0)]),...inc.map(x=>[INCOME_LABELS[x.incomeType]||x.incomeType,x.paymentDate,x.symbol||x.notes||'',Number(x.netAmount ?? ((x.grossAmount||0)-(x.taxAmount||0)))||0]),[],['Status do fechamento',close.status==='CLOSED'?'Fechado':'Aberto'],['Observações',close.notes||'']];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\n');downloadTextFile(`fechamento-${month}.csv`,csv,'text/csv;charset=utf-8');}

function demoRebalance(contribution){
  const currentTotal=Number(state.summary?.currentValue)||0, finalTotal=currentTotal+contribution, tolerance=Number(state.strategy?.tolerancePct)||0;
  const rows=strategyRows().map(x=>({label:x.className,targetPct:x.target,currentPct:x.current,currentValue:currentTotal*x.current/100,suggestedAmount:0}));
  const deficits=rows.map(x=>({...x,deficit:(x.targetPct-x.currentPct)>tolerance?Math.max(0,finalTotal*x.targetPct/100-x.currentValue):0}));
  let remaining=contribution;
  const totalDeficit=deficits.reduce((sum,x)=>sum+x.deficit,0);
  for(const x of deficits){if(totalDeficit>0){x.suggestedAmount=Math.min(x.deficit,contribution*x.deficit/totalDeficit);remaining-=x.suggestedAmount;}}
  if(remaining>0.01){const totalTarget=deficits.reduce((sum,x)=>sum+x.targetPct,0)||100;for(const x of deficits)x.suggestedAmount+=remaining*x.targetPct/totalTarget;}
  return {contribution,basis:'classes',tolerancePct:tolerance,note:`Prévia demonstrativa: priorização de desvios maiores que ±${tolerance.toFixed(2)}%.`,suggestions:deficits.sort((a,b)=>b.suggestedAmount-a.suggestedAmount).map(x=>({...x,afterPct:finalTotal?((x.currentValue+x.suggestedAmount)/finalTotal)*100:0}))};
}
function renderDecisionPlan(data){
  $('decisionPlanTitle').textContent=`Distribuição de ${money.format(data.contribution||0)}`;
  $('decisionPlanBasis').textContent=data.basis==='assets'?'metas por ativo':'metas por classe';
  $('decisionPlan').innerHTML=(data.suggestions||[]).filter(x=>x.suggestedAmount>0.005).map(x=>`<div class="decision-plan-row"><div><strong>${escapeHtml(x.label)}</strong><small>${fmtPct(x.currentPct)} hoje → ${fmtPct(x.afterPct)} depois · meta ${fmtPct(x.targetPct)}</small></div><div><small>Participação do aporte</small><strong>${fmtPct(data.contribution?x.suggestedAmount/data.contribution*100:0)}</strong></div><div class="amount">${money.format(x.suggestedAmount)}</div></div>`).join('')||'<div class="empty-state"><strong>Nenhuma distribuição calculada.</strong><p>Revise as metas e o valor do aporte.</p></div>';
}
async function calculateDecisionPlan(){
  const contribution=parsePtNumber($('decisionContributionInput').value);
  if(!Number.isFinite(contribution)||contribution<=0){toast('Informe um aporte maior que zero.');return;}
  const btn=$('decisionCalculateButton');setBusy(btn,true,'Calculando…');
  try{const data=state.preview?demoRebalance(contribution):await api('/api/rebalance',{method:'POST',body:JSON.stringify({contribution})});renderDecisionPlan(data);if(!state.preview)await refreshAll();}
  catch(e){toast(e.message);}finally{setBusy(btn,false);}
}
async function saveStrategy(){
  const tolerancePct=parsePtNumber($('strategyTolerance').value);
  if(!Number.isFinite(tolerancePct)||tolerancePct<0||tolerancePct>20){toast('A tolerância deve ficar entre 0% e 20%.');return;}
  const btn=$('saveStrategyButton');setBusy(btn,true,'Salvando…');
  try{
    if(state.preview){state.strategy={...state.strategy,tolerancePct};renderDecisionCenter();toast('Tolerância alterada apenas nesta prévia.');}
    else{state.strategy=await api('/api/strategy',{method:'PUT',body:JSON.stringify({tolerancePct})});renderDecisionCenter();renderInsights();toast('Tolerância salva.');}
  }catch(e){toast(e.message);}finally{setBusy(btn,false);}
}

