function renderHistory(){ const el=$('historyList'); if(!state.history.length){el.innerHTML='<p class="empty-text">Nenhuma atividade registrada ainda.</p>';return;} el.innerHTML=state.history.map(h=>`<div class="history-item"><small>${fmtDateTime(h.created_at)}</small><div><strong>${escapeHtml(historyTitle(h))}</strong><p>${escapeHtml(historyDetail(h))}</p></div><span class="badge">${escapeHtml(h.entity_type)}</span></div>`).join(''); }
