  if(bench.length>1){const a=Number(bench[0].value)||0,b=Number(bench[bench.length-1].value)||0;br=a?((b/a)-1)*100:0;}
  $('analysisPortfolioReturn').textContent=fmtPct(pr); $('analysisBenchmarkReturn').textContent=fmtPct(br); $('analysisGap').textContent=`${pct.format(pr-br)} p.p.`;
  const total=state.assets.reduce((s,a)=>s+(Number(a.currentValue)||0),0); const ranked=[...state.assets].sort((a,b)=>(b.currentValue||0)-(a.currentValue||0)); const top5=ranked.slice(0,5).reduce((s,a)=>s+(Number(a.currentValue)||0),0); const concentration=total?top5/total*100:0; $('analysisConcentration').textContent=fmtPct(concentration);
  $('analysisTopPositions').innerHTML=ranked.length?ranked.slice(0,6).map((a,i)=>{const w=total?(a.currentValue/total*100):0;return `<div class="analysis-row"><div><strong>${i+1}. ${escapeHtml(a.symbol)}</strong><small>${escapeHtml(a.assetClass)} · ${money.format(a.currentValue||0)}</small><div class="analysis-bar"><i style="width:${Math.min(100,w)}%"></i></div></div><div class="analysis-value">${fmtPct(w)}</div></div>`;}).join(''):'<div class="empty-state"><strong>Sem posições.</strong><p>Cadastre ativos para calcular concentração.</p></div>';
