  notes.push(`<div class="analysis-note"><strong>Concentração nas 5 maiores posições</strong>${fmtPct(concentration)} do patrimônio atual está concentrado nas cinco maiores posições.</div>`);
  if(points.length>1&&bench.length>1)notes.push(`<div class="analysis-note"><strong>Comparação no histórico disponível</strong>A carteira variou ${fmtPct(pr)} e o benchmark ${fmtPct(br)} no recorte disponível. A comparação é descritiva e depende das datas registradas.</div>`); else notes.push('<div class="analysis-note"><strong>Histórico ainda curto</strong>Com mais snapshots diários, a plataforma poderá exibir uma comparação temporal mais útil.</div>');
