function renderFiscal(){if(!$('fiscalYear'))return;const now=new Date().getFullYear(),years=new Set([now,...state.transactions.map(x=>Number(String(x.tradeDate||'').slice(0,4))),...state.income.map(x=>Number(String(x.paymentDate||'').slice(0,4)))]);const selected=Number($('fiscalYear').value)||Math.max(...[...years].filter(Number.isFinite));$('fiscalYear').innerHTML=[...years].filter(Number.isFinite).sort((a,b)=>b-a).map(y=>`<option value="${y}" ${y===selected?'selected':''}>${y}</option>`).join('');const year=selectedFiscalYear(),tx=fiscalYearTransactions(year),inc=fiscalYearIncome(year),sales=tx.filter(x=>x.kind==='SELL'),est=sales.map(fiscalSaleEstimate),salesGross=est.reduce((s,x)=>s+x.gross,0),result=est.reduce((s,x)=>s+x.result,0),incomeTax=inc.reduce((s,x)=>s+(Number(x.taxAmount)||0),0),monthsWithSales=new Set(sales.map(x=>String(x.tradeDate).slice(0,7))).size;$('fiscalSalesYear').textContent=money.format(salesGross);$('fiscalEstimatedResult').textContent=money.format(result);$('fiscalEstimatedResult').className=result>=0?'positive':'negative';$('fiscalIncomeTax').textContent=money.format(incomeTax);$('fiscalActiveMonths').textContent=String(monthsWithSales);$('fiscalPendingCaption').textContent=`${year} · ${sales.length} venda${sales.length===1?'':'s'} registrada${sales.length===1?'':'s'}`;const cfg=loadFiscalSettings();if(document.activeElement!==$('fiscalStockExemption'))$('fiscalStockExemption').value=number.format(cfg.stockExemption);if(document.activeElement!==$('fiscalCommonRate'))$('fiscalCommonRate').value=number.format(cfg.commonRate);if(document.activeElement!==$('fiscalDayTradeRate'))$('fiscalDayTradeRate').value=number.format(cfg.dayTradeRate);if(document.activeElement!==$('fiscalFiiRate'))$('fiscalFiiRate').value=number.format(cfg.fiiRate);renderFiscalMonths(year,cfg);renderFiscalHoldings();renderFiscalIncome(year);renderFiscalChecklist(year);}
function renderFiscalMonths(year,cfg){const months=Array.from({length:12},(_,i)=>`${year}-${String(i+1).padStart(2,'0')}`);const rows=months.map(m=>{const sales=state.transactions.filter(t=>t.kind==='SELL'&&String(t.tradeDate||'').slice(0,7)===m),calc=sales.map(fiscalSaleEstimate),gross=calc.reduce((s,x)=>s+x.gross,0),res=calc.reduce((s,x)=>s+x.result,0),stockGross=calc.filter(x=>x.assetClass==='Ações BR').reduce((s,x)=>s+x.gross,0),fiiRes=calc.filter(x=>x.assetClass==='FIIs').reduce((s,x)=>s+x.result,0),otherRes=res-fiiRes;let estimatedTax=Math.max(0,fiiRes)*(cfg.fiiRate/100);const stockExempt=stockGross>0&&stockGross<=cfg.stockExemption;estimatedTax+=Math.max(0,otherRes)*(stockExempt?0:cfg.commonRate/100);const [y,mm]=m.split('-'),label=new Date(Date.UTC(Number(y),Number(mm)-1,1)).toLocaleDateString('pt-BR',{month:'short',timeZone:'UTC'}).replace('.','');return {m,label,gross,res,estimatedTax,stockExempt,count:sales.length};});$('fiscalMonthlyTable').innerHTML=`<div class="fiscal-month-row header"><span>Mês</span><span>Vendas</span><span>Resultado estimado</span><span>IR estimado</span><span>Status</span></div>`+rows.map(r=>`<div class="fiscal-month-row"><strong>${r.label.toUpperCase()}</strong><span>${money.format(r.gross)}</span><span class="${r.res>=0?'positive':'negative'}">${money.format(r.res)}</span><span class="taxable">${money.format(r.estimatedTax)}</span><span class="${!r.count?'ok':r.stockExempt?'ok':'attention'}">${!r.count?'sem vendas':r.stockExempt?'revisar isenção':'conferir'}</span></div>`).join('');}
