function automationDefaults(){return {dailyEnabled:false,refreshQuotes:true,evaluateRules:true,duplicateGuard:true,runOncePerDay:true,staleQuoteHours:12,lastRunAt:null,lastRunSummary:{}};}
function normalizeAutomationSettings(value={}){const d=automationDefaults();return {...d,...value,dailyEnabled:value.dailyEnabled===true,refreshQuotes:value.refreshQuotes!==false,evaluateRules:value.evaluateRules!==false,duplicateGuard:value.duplicateGuard!==false,runOncePerDay:value.runOncePerDay!==false,staleQuoteHours:Math.max(1,Math.min(168,Math.round(Number(value.staleQuoteHours??d.staleQuoteHours)||d.staleQuoteHours))),lastRunSummary:value.lastRunSummary&&typeof value.lastRunSummary==='object'?value.lastRunSummary:{}};}
function automationPreviewKey(){return `pi-r18-automation-${state.user?.theme||'camile'}`;}
function loadPreviewAutomation(){try{const raw=JSON.parse(localStorage.getItem(automationPreviewKey())||'{}');return normalizeAutomationSettings(raw);}catch{return normalizeAutomationSettings({});}}
function savePreviewAutomation(){try{localStorage.setItem(automationPreviewKey(),JSON.stringify(state.automationSettings));}catch{}}
function automationFormSettings(){return normalizeAutomationSettings({dailyEnabled:Boolean($('autoDailyEnabled')?.checked),refreshQuotes:Boolean($('autoRefreshQuotes')?.checked),evaluateRules:Boolean($('autoEvaluateRules')?.checked),duplicateGuard:Boolean($('autoDuplicateGuard')?.checked),runOncePerDay:Boolean($('autoOnceDaily')?.checked),staleQuoteHours:Number($('autoStaleHours')?.value)||12,lastRunAt:state.automationSettings?.lastRunAt,lastRunSummary:state.automationSettings?.lastRunSummary||{}});}
function sameLocalDay(value){if(!value)return false;const d=new Date(value),n=new Date();return Number.isFinite(d.getTime())&&d.getFullYear()===n.getFullYear()&&d.getMonth()===n.getMonth()&&d.getDate()===n.getDate();}
function automationSummaryText(summary={}){const parts=[];if(summary.quotes!=null)parts.push(`${summary.quotes} cotação(ões)`);if(summary.quotesSkipped)parts.push('cotações ainda recentes');if(summary.snapshot)parts.push('snapshot');if(summary.rules!=null)parts.push(`${summary.rules} sinal(is)`);if(summary.errors)parts.push(`${summary.errors} falha(s)`);return parts.length?parts.join(' · '):'rotina concluída';}
function importTypeLabel(type){return ({POSITIONS:'Posições',TRANSACTIONS:'Movimentações',INCOME:'Proventos',AUTO:'Automático'})[type]||type||'Importação';}
function importStatusLabel(status){return ({COMPLETED:'concluído',PARTIAL:'parcial',FAILED:'falhou'})[status]||String(status||'').toLowerCase();}

function reconciliationRows(){
  const bySymbol=new Map();
  for(const t of state.transactions||[]){if(!t.symbol||!['BUY','SELL'].includes(t.kind))continue;const key=String(t.symbol).toUpperCase(),row=bySymbol.get(key)||{buys:0,sells:0,count:0};if(t.kind==='BUY')row.buys+=Number(t.quantity)||0;else row.sells+=Number(t.quantity)||0;row.count++;bySymbol.set(key,row);}
  const order={warn:0,neutral:1,ok:2};return (state.assets||[]).map(a=>{const h=bySymbol.get(String(a.symbol).toUpperCase()),current=Number(a.quantity)||0;if(!h)return {symbol:a.symbol,name:a.name,current,ledger:null,diff:null,status:'neutral',label:'sem histórico'};const ledger=h.buys-h.sells,diff=current-ledger,ok=Math.abs(diff)<=1e-6;return {symbol:a.symbol,name:a.name,current,ledger,diff,status:ok?'ok':'warn',label:ok?'reconciliado':'diferença',count:h.count};}).sort((a,b)=>(order[a.status]??9)-(order[b.status]??9));
}
function renderReconciliation(){const el=$('reconciliationList');if(!el)return;const rows=reconciliationRows(),warn=rows.filter(x=>x.status==='warn').length,ok=rows.filter(x=>x.status==='ok').length;$('reconcileBadge').textContent=warn?`${warn} diferença${warn===1?'':'s'}`:ok?`${ok} conciliado${ok===1?'':'s'}`:'indicativo';el.innerHTML=rows.length?rows.slice(0,9).map(x=>`<div class="r18-reconcile-row"><div><strong>${escapeHtml(x.symbol)} · ${escapeHtml(x.name||'')}</strong><small>${x.ledger==null?'Nenhuma compra/venda registrada para reconstruir a posição':`${x.count} operação(ões) no histórico`}</small></div><div class="r18-reconcile-qty"><strong>${number.format(x.current)}</strong><small>${x.ledger==null?'posição atual':`histórico ${number.format(x.ledger)}`}</small></div><span class="r18-reconcile-status ${x.status}">${x.label}${x.diff==null?'':` · ${x.diff>0?'+':''}${number.format(x.diff)}`}</span></div>`).join(''):'<div class="empty-state"><strong>Nenhuma posição para reconciliar.</strong><p>Cadastre ou importe ativos para usar esta conferência.</p></div>';}

function renderImportHistory(){const el=$('r18ImportHistory');if(!el)return;const rows=state.importHistory||[];$('importHistoryBadge').textContent=`${rows.length} lote${rows.length===1?'':'s'}`;el.innerHTML=rows.length?rows.slice(0,12).map(x=>`<div class="r18-history-row"><div><span class="r18-batch-type">${escapeHtml(importTypeLabel(x.type))}</span><strong>${escapeHtml(x.fileName||'arquivo')}</strong><small>${fmtDateTime(x.createdAt)} · ${escapeHtml(importStatusLabel(x.status))}</small></div><span>${number.format(Number(x.inserted||0)+Number(x.updated||0))} gravadas</span><span>${number.format(Number(x.duplicates||0))} duplicadas</span><span>${number.format(Number(x.errors||0))} erros</span></div>`).join(''):'<div class="empty-state"><strong>Nenhum lote importado ainda.</strong><p>As importações confirmadas aparecerão aqui com data, arquivo e contagens.</p></div>';}
function renderImportPreview(){const box=$('r18ImportPreview'),preview=state.importPreview;if(!box)return;if(!preview){box.hidden=true;$('r18CommitImport').disabled=true;$('importDetectedBadge').textContent=state.importFile?'aguardando análise':'nenhum arquivo';return;}box.hidden=false;const sum=preview.summary||{};$('r18PreviewTotal').textContent=number.format(sum.total||0);$('r18PreviewValid').textContent=number.format(sum.valid??sum.inserted??0);$('r18PreviewDuplicates').textContent=number.format(sum.duplicates||0);$('r18PreviewErrors').textContent=number.format(sum.errors||0);$('importDetectedBadge').textContent=importTypeLabel(preview.detectedType||state.importType);const rows=preview.rows||[];$('r18PreviewTable').innerHTML=`<div class="r18-preview-row header"><span>Linha</span><span>Registro</span><span>Data / detalhe</span><span class="numeric">Valor</span><span class="numeric">Status</span></div>${rows.map(r=>`<div class="r18-preview-row"><span>${r.row??'—'}</span><strong>${escapeHtml(r.main||'')}</strong><span>${escapeHtml(r.detail||r.error||'')}</span><span class="numeric">${Number.isFinite(Number(r.value))?money.format(Number(r.value)):'—'}</span><span class="r18-preview-status ${r.status||'ok'}">${r.status==='duplicate'?'duplicada':r.status==='error'?'erro':'pronta'}</span></div>`).join('')}`;$('r18CommitImport').disabled=(Number(sum.valid??0)<=0&&!state.preview);}
function renderAutomationStudio(){if(!$('automationSection'))return;const a=normalizeAutomationSettings(state.automationSettings||{});state.automationSettings=a;if(document.activeElement!==$('autoDailyEnabled'))$('autoDailyEnabled').checked=a.dailyEnabled;if(document.activeElement!==$('autoRefreshQuotes'))$('autoRefreshQuotes').checked=a.refreshQuotes;if(document.activeElement!==$('autoEvaluateRules'))$('autoEvaluateRules').checked=a.evaluateRules;if(document.activeElement!==$('autoDuplicateGuard'))$('autoDuplicateGuard').checked=a.duplicateGuard;if(document.activeElement!==$('autoOnceDaily'))$('autoOnceDaily').checked=a.runOncePerDay;if(document.activeElement!==$('autoStaleHours'))$('autoStaleHours').value=String(a.staleQuoteHours);$('automationStatusBadge').textContent=a.dailyEnabled?'automática':'manual';$('automationLastRun').textContent=a.lastRunAt?fmtDateTime(a.lastRunAt):'Nunca';$('automationLastRunDetail').textContent=a.lastRunAt?automationSummaryText(a.lastRunSummary):'nenhuma execução registrada';const hist=state.importHistory||[];$('automationImportCount').textContent=number.format(hist.length);$('automationRowsProcessed').textContent=number.format(hist.reduce((s,x)=>s+Number(x.total||0),0));$('automationDuplicateCount').textContent=number.format(hist.reduce((s,x)=>s+Number(x.duplicates||0),0));const run=$('automationRunSummary');if(run){const sum=a.lastRunSummary||{};run.innerHTML=a.lastRunAt?`<span class="r18-run-orb">✓</span><div><strong>Última rotina: ${escapeHtml(automationSummaryText(sum))}</strong><small>${fmtDateTime(a.lastRunAt)}. A rotina não executa ordens nem altera suas metas.</small></div>`:`<span class="r18-run-orb">AI</span><div><strong>Automação sob seu controle</strong><small>A rotina nunca compra, vende ou altera metas. Ela apenas atualiza dados, registra snapshot e reavalia sinais.</small></div>`;}document.querySelectorAll('.r18-import-type').forEach(b=>b.classList.toggle('active',b.dataset.importType===state.importType));$('r18ImportFileName').textContent=state.importFile?.name||'Nenhum arquivo selecionado';renderReconciliation();renderImportHistory();renderImportPreview();}

async function saveAutomationSettings(){const btn=$('saveAutomationSettings'),next=automationFormSettings();setBusy(btn,true,'Salvando…');try{if(state.preview){state.automationSettings=next;savePreviewAutomation();}else{const data=await api('/api/automation-settings',{method:'PUT',body:JSON.stringify(next)});state.automationSettings=normalizeAutomationSettings(data.settings||next);}renderAutomationStudio();toast('Automações salvas para este perfil.');}catch(e){toast(e.message);}finally{setBusy(btn,false);}}
async function runAutomationRoutine({silent=false,automatic=false}={}){if(state.automationRunning)return;const settings=automatic?normalizeAutomationSettings(state.automationSettings):automationFormSettings();if(automatic&&settings.runOncePerDay&&sameLocalDay(settings.lastRunAt))return;state.automationRunning=true;const btn=$('runAutomationNow');if(!silent)setBusy(btn,true,'Executando…');const result={quotes:0,quotesSkipped:false,snapshot:false,rules:0,errors:0,automatic};try{if(state.preview){await new Promise(r=>setTimeout(r,350));result.quotes=state.assets.filter(a=>a.autoQuote).length;result.snapshot=true;result.rules=evaluateRuleSignals().length;state.automationSettings={...settings,lastRunAt:new Date().toISOString(),lastRunSummary:result};savePreviewAutomation();renderAutomationStudio();if(!silent)toast('Prévia: rotina automática simulada.');return;}const lastQuoteAt=state.summary?.lastQuoteAt?new Date(state.summary.lastQuoteAt).getTime():0;const staleAfter=Math.max(1,Number(settings.staleQuoteHours)||12)*3600000;const quoteRefreshNeeded=!automatic||!lastQuoteAt||(Date.now()-lastQuoteAt)>=staleAfter;if(settings.refreshQuotes&&quoteRefreshNeeded){try{const market=await api('/api/market',{method:'POST',body:'{}'});result.quotes=(market.results||[]).filter(x=>x.ok).length;const fresh=await api('/api/assets');state.assets=fresh.assets||state.assets;state.classes=fresh.classes||state.classes;}catch{result.errors++;}}else if(settings.refreshQuotes){result.quotesSkipped=true;}try{state.performance=await api('/api/performance');result.snapshot=true;}catch{result.errors++;}if(settings.evaluateRules){try{const signals=evaluateRuleSignals();result.rules=signals.length;if(signals.length)await api('/api/decision-rules',{method:'POST',body:JSON.stringify({events:signals})});}catch{result.errors++;}}const marked=await api('/api/automation-settings',{method:'POST',body:JSON.stringify({summary:result})});state.automationSettings=normalizeAutomationSettings(marked.settings||{...settings,lastRunAt:new Date().toISOString(),lastRunSummary:result});await refreshAll();if(!silent)toast(result.errors?'Rotina concluída com pontos de atenção.':'Rotina concluída.');}catch(e){if(!silent)toast(e.message);}finally{state.automationRunning=false;if(!silent)setBusy(btn,false);renderAutomationStudio();}}
async function maybeRunDailyAutomation(){if(state.preview||state.automationRunning)return;const a=normalizeAutomationSettings(state.automationSettings||{});if(!a.dailyEnabled)return;if(a.runOncePerDay&&sameLocalDay(a.lastRunAt))return;await runAutomationRoutine({silent:true,automatic:true});}

function chooseImportType(type){state.importType=['AUTO','POSITIONS','TRANSACTIONS','INCOME'].includes(type)?type:'AUTO';state.importPreview=null;renderAutomationStudio();}
function selectImportFile(file){if(!file)return;const name=String(file.name||'').toLowerCase();if(!name.endsWith('.csv')&&!name.endsWith('.xlsx')){toast('Use um arquivo CSV ou XLSX.');return;}if(file.size>8*1024*1024){toast('O arquivo deve ter no máximo 8 MB.');return;}state.importFile=file;state.importPreview=null;$('r18ImportMessage').hidden=true;renderAutomationStudio();}
function r18ParseCsv(text){const first=(text.split(/\r?\n/,1)[0]||''),sep=first.includes(';')?';':first.includes('\t')?'\t':',';const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(ch===sep&&!quoted){row.push(field);field='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(field);field='';if(row.some(x=>x.trim()))rows.push(row);row=[];}else field+=ch;}row.push(field);if(row.some(x=>x.trim()))rows.push(row);return rows;}
function r18Norm(v){return String(v??'').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ');}
function r18PreviewCsvRows(rows,type){if(rows.length<2)return null;const headers=rows[0].map(r18Norm),has=(...names)=>headers.some(h=>names.includes(h));let detected=type;if(type==='AUTO'){if(has('preco medio','pm')&&has('quantidade','qtd'))detected='POSITIONS';else if(has('ir','imposto','irrf'))detected='INCOME';else detected='TRANSACTIONS';}const out=[];let errors=0;for(let i=1;i<rows.length&&out.length<100;i++){const r=rows[i];if(!r.some(x=>String(x).trim()))continue;const get=(names)=>{const idx=headers.findIndex(h=>names.includes(h));return idx>=0?r[idx]:''};let main='',detail='',value=0,status='ok',error='';if(detected==='POSITIONS'){main=String(get(['ticker','codigo','ativo','symbol'])).toUpperCase();detail=get(['classe','class'])||'posição';value=parsePtNumber(get(['preco medio','pm','averageprice']))||0;if(!main){status='error';error='Ticker ausente.';}}else if(detected==='TRANSACTIONS'){const kind=get(['tipo','operacao','movimento']);const symbol=String(get(['ticker','codigo','ativo','symbol'])).toUpperCase();main=`${kind||'Movimentação'}${symbol?` · ${symbol}`:''}`;detail=get(['data','data da operacao','date'])||'';value=parsePtNumber(get(['valor','amount']))||((parsePtNumber(get(['quantidade','qtd']))||0)*(parsePtNumber(get(['preco','preco unitario','valor unitario']))||0));if(!kind||!detail){status='error';error='Tipo ou data ausente.';}}else{const kind=get(['tipo','evento']);const symbol=String(get(['ticker','codigo','ativo','symbol'])).toUpperCase();main=`${kind||'Provento'}${symbol?` · ${symbol}`:''}`;detail=get(['data pagamento','data do pagamento','data','date'])||'';value=parsePtNumber(get(['valor bruto','bruto','valor','gross']))||0;if(!kind||!detail){status='error';error='Tipo ou data ausente.';}}if(status==='error')errors++;out.push({row:i+1,status,error,main,detail,value});}return {mode:'preview',detectedType:detected,summary:{total:out.length,valid:out.length-errors,duplicates:0,errors},rows:out};}
function demoImportPreview(type='AUTO'){const detected=type==='AUTO'?'TRANSACTIONS':type;if(detected==='POSITIONS')return {mode:'preview',detectedType:'POSITIONS',summary:{total:4,valid:4,duplicates:0,errors:0},rows:[{row:2,status:'ok',main:'PETR4',detail:'Ações BR · 220 un.',value:34.10},{row:3,status:'ok',main:'HGLG11',detail:'FIIs · 48 un.',value:158.20},{row:4,status:'ok',main:'IVVB11',detail:'Exterior · 125 un.',value:279.20},{row:5,status:'ok',main:'TESOURO-SELIC',detail:'Renda Fixa · 1 un.',value:72000}]};if(detected==='INCOME')return {mode:'preview',detectedType:'INCOME',summary:{total:4,valid:3,duplicates:1,errors:0},rows:[{row:2,status:'ok',main:'DIVIDEND · PETR4',detail:'2026-09-10',value:185},{row:3,status:'duplicate',main:'FII_INCOME · HGLG11',detail:'2026-09-10',value:52.8},{row:4,status:'ok',main:'JCP · ITUB4',detail:'2026-09-12',value:94.5},{row:5,status:'ok',main:'INTEREST · TESOURO-SELIC',detail:'2026-09-15',value:138.2}]};return {mode:'preview',detectedType:'TRANSACTIONS',summary:{total:5,valid:4,duplicates:1,errors:0},rows:[{row:2,status:'ok',main:'BUY · IVVB11',detail:'2026-09-12',value:2982},{row:3,status:'duplicate',main:'DEPOSIT',detail:'2026-09-05',value:5000},{row:4,status:'ok',main:'BUY · HGLG11',detail:'2026-08-28',value:488.1},{row:5,status:'ok',main:'SELL · PETR4',detail:'2026-08-20',value:1920},{row:6,status:'ok',main:'WITHDRAWAL',detail:'2026-08-15',value:1000}]};}
async function analyzeImportFile(){if(!state.importFile&&state.preview){state.importPreview=demoImportPreview(state.importType);renderAutomationStudio();toast('Prévia demonstrativa carregada.');return;}if(!state.importFile){toast('Escolha um arquivo antes de analisar.');return;}const btn=$('r18AnalyzeImport');setBusy(btn,true,'Analisando…');$('r18ImportMessage').hidden=true;try{if(state.preview){if(String(state.importFile.name).toLowerCase().endsWith('.csv')){const text=await state.importFile.text();state.importPreview=r18PreviewCsvRows(r18ParseCsv(text),state.importType)||demoImportPreview(state.importType);}else{state.importPreview=demoImportPreview(state.importType);$('r18ImportMessage').hidden=false;$('r18ImportMessage').textContent='Na prévia standalone, XLSX usa dados demonstrativos. A versão publicada analisa o arquivo XLSX real no backend.';}renderAutomationStudio();return;}const form=new FormData();form.append('file',state.importFile);form.append('importType',state.importType);form.append('mode','preview');form.append('duplicateGuard',String($('autoDuplicateGuard').checked));state.importPreview=await api('/api/imports',{method:'POST',body:form});renderAutomationStudio();}catch(e){$('r18ImportMessage').hidden=false;$('r18ImportMessage').textContent=e.message;toast(e.message);}finally{setBusy(btn,false);}}
async function commitImportFile(){if(!state.importPreview){toast('Analise o arquivo antes de confirmar.');return;}const btn=$('r18CommitImport');setBusy(btn,true,'Importando…');try{if(state.preview){const p=state.importPreview,sum=p.summary||{},batch={id:Date.now(),type:p.detectedType,fileName:state.importFile?.name||'demonstracao-r18.csv',status:(sum.errors||0)?'PARTIAL':'COMPLETED',total:sum.total||0,inserted:sum.valid||0,updated:0,duplicates:sum.duplicates||0,errors:sum.errors||0,applyToPositions:Boolean($('r18ApplyToPositions').checked),createdAt:new Date().toISOString()};state.importHistory=[batch,...state.importHistory];state.importPreview=null;state.importFile=null;renderAutomationStudio();$('r18ImportMessage').hidden=false;$('r18ImportMessage').innerHTML='<strong>Prévia:</strong> importação simulada e adicionada ao histórico local.';toast('Prévia: importação simulada.');return;}if(!state.importFile)throw new Error('O arquivo original precisa continuar selecionado.');const form=new FormData();form.append('file',state.importFile);form.append('importType',state.importPreview.detectedType||state.importType);form.append('mode','commit');form.append('duplicateGuard',String($('autoDuplicateGuard').checked));form.append('applyToPositions',String($('r18ApplyToPositions').checked));const data=await api('/api/imports',{method:'POST',body:form});state.importHistory=data.history||state.importHistory;$('r18ImportMessage').hidden=false;$('r18ImportMessage').innerHTML=`<strong>Importação concluída:</strong> ${data.summary.inserted||0} inserida(s), ${data.summary.updated||0} atualizada(s), ${data.summary.duplicates||0} duplicada(s) bloqueada(s), ${data.summary.errors||0} erro(s).`;state.importPreview=null;state.importFile=null;await refreshAll();toast('Importação concluída.');}catch(e){$('r18ImportMessage').hidden=false;$('r18ImportMessage').textContent=e.message;toast(e.message);}finally{setBusy(btn,false);renderAutomationStudio();}}

function switchSection(section){ document.querySelectorAll('.view-section').forEach(s=>{s.hidden=s.id!==`${section}Section`;s.classList.toggle('active-section',!s.hidden);}); document.querySelectorAll('.nav-item[data-section]').forEach(b=>{const active=b.dataset.section===section;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}); if(section==='performance')requestAnimationFrame(drawPerformanceCharts); if(section==='wealth')requestAnimationFrame(drawWealthCharts); if(section==='fiscal')renderFiscal(); if(section==='automation')renderAutomationStudio(); if(section==='security')renderSecurityCenter(); if(section==='cloud')renderCloudCenter(); if(section==='integrations')loadIntegrations({silent:true}); if(section==='reconciliation')renderReconciliationCenter(); if(section==='release'){renderReleaseCenter();if(!state.preview&&!state.launchReadiness&&!state.launchLoading)loadR36LaunchReadiness({silent:true});} if(section==='analysis')requestAnimationFrame(drawAnalysisChart); if(section==='overview')requestAnimationFrame(drawPerformanceCharts); if(section==='live'){if(!state.live||Date.now()-new Date(state.live.requestedAt||0).getTime()>60000)refreshLiveMarket(null,{silent:true});if(!state.liveDetail)loadLiveDetail();if(!state.liveEvents)refreshLiveEvents();requestAnimationFrame(drawLiveHistoryChart);} if(section==='closing')renderClosing(); if(section==='reports')renderReports(); if(section==='rules')renderRules(); if(section==='agenda'&&!state.preview&&(!state.agenda?.requestedAt||Date.now()-new Date(state.agenda.requestedAt).getTime()>300000))refreshAgenda(null); }
function openAssetDialog(asset=null){ $('assetForm').reset(); $('assetFormError').textContent=''; $('assetId').value=asset?.id||''; $('assetDialogTitle').textContent=asset?'Editar investimento':'Adicionar investimento'; $('deleteAssetButton').hidden=!asset; populateClassSelect(); if(asset){ $('assetSymbol').value=asset.symbol;$('assetName').value=asset.name;$('assetClass').value=asset.assetClass;$('assetType').value=asset.assetType;$('assetQuantity').value=number.format(asset.quantity);$('assetAveragePrice').value=number.format(asset.averagePrice);$('assetManualPrice').value=asset.manualPrice==null?'':number.format(asset.manualPrice);$('assetTargetPct').value=number.format(asset.targetPct);$('assetAutoQuote').checked=asset.autoQuote;$('assetNotes').value=asset.notes||''; } $('assetDialog').showModal(); }
async function saveAsset(event){ event.preventDefault(); if(previewOnlyAction())return; const btn=$('saveAssetButton'),id=Number($('assetId').value)||null; const body={id,symbol:$('assetSymbol').value,name:$('assetName').value,assetClass:$('assetClass').value,assetType:$('assetType').value,quantity:parsePtNumber($('assetQuantity').value),averagePrice:parsePtNumber($('assetAveragePrice').value),manualPrice:$('assetManualPrice').value.trim()===''?null:parsePtNumber($('assetManualPrice').value),targetPct:parsePtNumber($('assetTargetPct').value),autoQuote:$('assetAutoQuote').checked,notes:$('assetNotes').value}; if(Object.values(body).some(v=>typeof v==='number'&&Number.isNaN(v))){$('assetFormError').textContent='Revise os números informados.';return;} setBusy(btn,true); try{await api('/api/assets',{method:id?'PATCH':'POST',body:JSON.stringify(body)});$('assetDialog').close();await refreshAll();toast(id?'Ativo atualizado.':'Ativo adicionado.');}catch(e){$('assetFormError').textContent=e.message;}finally{setBusy(btn,false);} }
async function deleteAsset(){ if(previewOnlyAction())return; const id=Number($('assetId').value); if(!id||!confirm('Excluir esta posição da carteira? O histórico de atividade será preservado.'))return; const btn=$('deleteAssetButton');setBusy(btn,true,'Excluindo…');try{await api('/api/assets',{method:'DELETE',body:JSON.stringify({id})});$('assetDialog').close();await refreshAll();toast('Ativo excluído.');}catch(e){toast(e.message);}finally{setBusy(btn,false);} }

function toggleTransactionFields(){ const cash=['DEPOSIT','WITHDRAWAL'].includes($('transactionKind').value); $('transactionAssetFields').hidden=cash; $('transactionCashFields').hidden=!cash; }
function openTransactionDialog(){ $('transactionForm').reset();$('transactionError').textContent='';$('transactionDate').value=today();populateAssetSelects();toggleTransactionFields();$('transactionDialog').showModal(); }
async function saveTransaction(event){ event.preventDefault(); if(previewOnlyAction())return; const kind=$('transactionKind').value, cash=['DEPOSIT','WITHDRAWAL'].includes(kind); const body={kind,tradeDate:$('transactionDate').value,fees:parsePtNumber($('transactionFees').value)||0,notes:$('transactionNotes').value}; if(cash)body.amount=parsePtNumber($('transactionAmount').value);else{body.assetId=Number($('transactionAsset').value);body.quantity=parsePtNumber($('transactionQuantity').value);body.unitPrice=parsePtNumber($('transactionPrice').value);} const btn=$('saveTransactionButton');setBusy(btn,true);try{await api('/api/transactions',{method:'POST',body:JSON.stringify(body)});$('transactionDialog').close();await refreshAll();toast('Movimentação registrada.');}catch(e){$('transactionError').textContent=e.message;}finally{setBusy(btn,false);} }
function openIncomeDialog(){ $('incomeForm').reset();$('incomeError').textContent='';$('incomeDate').value=today();populateAssetSelects();$('incomeDialog').showModal(); }
async function saveIncome(event){ event.preventDefault(); if(previewOnlyAction())return; const body={incomeType:$('incomeType').value,assetId:$('incomeAsset').value?Number($('incomeAsset').value):null,paymentDate:$('incomeDate').value,grossAmount:parsePtNumber($('incomeGross').value),taxAmount:parsePtNumber($('incomeTax').value)||0,notes:$('incomeNotes').value}; const btn=$('saveIncomeButton');setBusy(btn,true);try{await api('/api/income',{method:'POST',body:JSON.stringify(body)});$('incomeDialog').close();await refreshAll();toast('Provento registrado.');}catch(e){$('incomeError').textContent=e.message;}finally{setBusy(btn,false);} }
function openWatchDialog(item=null){ $('watchForm').reset();$('watchError').textContent='';$('watchId').value=item?.id||'';$('watchDialogTitle').textContent=item?'Editar watchlist':'Adicionar à watchlist';$('deleteWatchButton').hidden=!item;$('watchSymbol').disabled=Boolean(item);if(item){$('watchSymbol').value=item.symbol;$('watchName').value=item.name;$('watchTarget').value=item.targetBuyPrice==null?'':number.format(item.targetBuyPrice);$('watchChangeAlert').value=item.alertChangePct==null?'':number.format(item.alertChangePct);$('watchNotes').value=item.notes||'';}$('watchDialog').showModal(); }
async function saveWatch(event){ event.preventDefault(); if(previewOnlyAction())return; const id=Number($('watchId').value)||null,body={id,symbol:$('watchSymbol').value,name:$('watchName').value,targetBuyPrice:$('watchTarget').value.trim()===''?null:parsePtNumber($('watchTarget').value),alertChangePct:$('watchChangeAlert').value.trim()===''?null:parsePtNumber($('watchChangeAlert').value),notes:$('watchNotes').value};const btn=$('saveWatchButton');setBusy(btn,true);try{await api('/api/watchlist',{method:id?'PATCH':'POST',body:JSON.stringify(body)});$('watchDialog').close();await refreshAll();toast('Watchlist atualizada.');}catch(e){$('watchError').textContent=e.message;}finally{setBusy(btn,false);} }
