function drawPerformanceCharts(){
  const points=state.performance?.points||[]; drawLineChart('overviewChart',points.map(x=>({x:x.date,y:x.marketValue})),[{key:'y',color:'--series-1'}],$('overviewChartEmpty')); drawLineChart('performanceChart',points,[{key:'marketValue',color:'--series-1'},{key:'investedValue',color:'--series-3'}],$('performanceChartEmpty'));
  const raw=state.performance?.benchmark?.points||[]; let normalized=[]; if(raw.length>1){const base=raw[0].value;normalized=raw.map(x=>({date:x.date,index:(x.value/base)*100}));} drawLineChart('benchmarkChart',normalized,[{key:'index',color:'--series-2'}],$('benchmarkChartEmpty'),true);
}
function drawLineChart(canvasId,points,series,emptyEl,indexMode=false){
  const canvas=$(canvasId); if(!canvas)return; const parent=canvas.parentElement; const width=Math.max(260,parent.clientWidth||600),height=parent.classList.contains('large-chart')?300:parent.classList.contains('benchmark-chart')?220:180; const dpr=Math.max(1,Math.min(2,window.devicePixelRatio||1)); canvas.width=Math.floor(width*dpr);canvas.height=Math.floor(height*dpr);canvas.style.width=`${width}px`;canvas.style.height=`${height}px`;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,width,height);
  if(points.length<2){emptyEl.hidden=false;canvas.hidden=true;return;} emptyEl.hidden=true;canvas.hidden=false; const vals=[];series.forEach(s=>points.forEach(p=>{const v=Number(p[s.key]);if(Number.isFinite(v))vals.push(v);}));if(!vals.length)return;let min=Math.min(...vals),max=Math.max(...vals);if(min===max){min*=.95;max*=1.05;} const pad={l:12,r:12,t:16,b:22},iw=width-pad.l-pad.r,ih=height-pad.t-pad.b; const styles=getComputedStyle(document.body);
  ctx.strokeStyle=styles.getPropertyValue('--line').trim()||'#ddd';ctx.lineWidth=1;for(let i=0;i<4;i++){const y=pad.t+(ih*i/3);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(width-pad.r,y);ctx.stroke();}
  series.forEach(s=>{ctx.strokeStyle=styles.getPropertyValue(s.color).trim()||'#111';ctx.lineWidth=2;ctx.beginPath();let started=false;points.forEach((p,i)=>{const v=Number(p[s.key]);if(!Number.isFinite(v))return;const x=pad.l+(i/(points.length-1))*iw,y=pad.t+((max-v)/(max-min))*ih;if(!started){ctx.moveTo(x,y);started=true;}else ctx.lineTo(x,y);});ctx.stroke();});
  ctx.fillStyle=styles.getPropertyValue('--muted').trim()||'#666';ctx.font='10px DM Sans, sans-serif';ctx.fillText(fmtDate(points[0].date||points[0].x),pad.l,height-6);const end=fmtDate(points[points.length-1].date||points[points.length-1].x);ctx.fillText(end,width-pad.r-ctx.measureText(end).width,height-6); if(indexMode){ctx.fillText(`${pct.format(max-100)}%`,pad.l,pad.t+10);}
}


