function exitPreview(){
  stopLiveTimers();state.preview=false;document.body.classList.remove('preview-mode');$('previewBanner').hidden=true;showLogin();checkPlatformStatus();
}
function previewOnlyAction(){
  if(!state.preview)return false;toast('Prévia demonstrativa: esta ação não grava dados.');return true;
}

async function checkPlatformStatus(){
  const el=$('platformStatus'); if(!el)return;
  if(location.protocol==='file:'){
    el.className='platform-status preview';
    el.innerHTML='<span class="status-dot"></span><span>Prévia local da Rodada 36. Valores pessoais começam zerados; conciliação e casos acompanham cada dado adicionado.</span>';
    if($('initialSetupPanel'))$('initialSetupPanel').hidden=true;
    return false;
  }
  try{
    const response=await fetch('/api/deployment-status',{headers:{accept:'application/json'},cache:'no-store'});
    const data=await response.json().catch(()=>({})); state.deploymentStatus=data;
    if(!response.ok)throw new Error(data.error||'backend indisponível');
    if($('initialSetupPanel'))$('initialSetupPanel').hidden=!data.setupRequired;
    if(data.setupRequired){
      el.className='platform-status preview';
      el.innerHTML='<span class="status-dot"></span><span>Publicação conectada. Falta concluir a ativação inicial dos dois usuários.</span>';
      return true;
    }
    el.className='platform-status ok';
    el.innerHTML=`<span class="status-dot"></span><span>${data.https?'HTTPS ativo':'Ambiente conectado'} · banco persistente · Rodada 36 online.</span>`;
    return true;
  }catch{
    if($('initialSetupPanel'))$('initialSetupPanel').hidden=true;
    el.className='platform-status error';
    el.innerHTML='<span class="status-dot"></span><span>Servidor não conectado. Use a URL publicada ou inicie o ambiente Netlify.</span>';
    return false;
  }
}




