function normalizeIntegrationSettings(v={}){return {marketEnabled:v.marketEnabled!==false,agendaEnabled:v.agendaEnabled!==false,benchmarksEnabled:v.benchmarksEnabled!==false,autoSyncEnabled:v.autoSyncEnabled===true,syncHourLocal:Math.max(0,Math.min(23,Number(v.syncHourLocal??7)||0)),lastSyncAt:v.lastSyncAt||null,lastSyncSummary:v.lastSyncSummary||{}}}
async function loadIntegrations({silent=true}={}){
  if(state.preview){state.integrations=demoIntegrations();renderIntegrations();return state.integrations;}
  if(state.integrationLoading)return state.integrations;state.integrationLoading=true;
  try{state.integrations=await api('/api/integrations');renderIntegrations();return state.integrations}catch(e){if(!silent)toast(e.message);return null}finally{state.integrationLoading=false}
}
function integrationProviderIcon(key){return {brapi:'◈',twelve:'12',finnhub:'F',news:'N',db:'DB',scheduler:'↻'}[key]||'•'}
