  $('cloudEnvironmentBadge').textContent=c.published?'publicado':(state.preview?'prévia':'ambiente local');
  $('cloudReadiness').innerHTML=checks.map(([k,t,ok,d])=>`<div class="r22-readiness-row ${ok?'good':'warn'}"><span>${ok?'✓':'!'}</span><div><strong>${escapeHtml(t)}</strong><small>${escapeHtml(d)}</small></div><b>${ok?'ok':'revisar'}</b></div>`).join('');
  $('cloudDataCards').innerHTML=`<div><span>Banco</span><strong>${c.database?'Persistente':'Indisponível'}</strong><small>${c.database?'Netlify Database / Postgres':'Verifique a publicação'}</small></div><div><span>Carteira</span><strong>${c.portfolioReady?'Vinculada':'Pendente'}</strong><small>dados separados por perfil</small></div><div><span>Snapshot</span><strong>${c.latestSnapshotAt?fmtDateTime(c.latestSnapshotAt):'—'}</strong><small>último registro patrimonial</small></div><div><span>Sessões</span><strong>${number.format(c.activeSessions||0)}</strong><small>ativas neste usuário</small></div>`;
  $('cloudBackupBadge').textContent=c.automaticBackupEnabled?String(c.backupFrequency||'AUTO').toLowerCase():'desativado';
  $('cloudBackupSummary').innerHTML=`<div><span>Última cópia</span><strong>${c.lastBackupAt?fmtDateTime(c.lastBackupAt):'Nenhuma ainda'}</strong></div><div><span>Origem</span><strong>${escapeHtml(c.lastBackupLabel||'—')}</strong></div><div><span>Rotina</span><strong>${c.scheduledBackups?'Agendada':'Somente manual'}</strong></div>`;
  $('cloudSessionBadge').textContent=c.sessionServerSide?'server-side':'revisar';
  $('cloudSessionSummary').innerHTML=`<div><strong>${c.sessionServerSide?'Expiração dupla':'Somente navegador'}</strong><p>O navegador bloqueia por inatividade e o backend rejeita sessões que ultrapassam o mesmo limite.</p></div><div><strong>Cookie privado</strong><p>HttpOnly + SameSite=Strict; em HTTPS, o cookie recebe Secure.</p></div>`;
