function defaultGovernancePolicy(){return {objective:'',horizonYears:10,reviewFrequencyMonths:6,maxAssetWeightPct:20,minCashPct:5,liquidityNote:'',principles:'',restrictedAssets:'',stressShocks:{},updatedAt:null};}
function normalizeGovernancePolicy(p={}){const d=defaultGovernancePolicy(),shocks=(p&&typeof p.stressShocks==='object'&&p.stressShocks)?p.stressShocks:{};return {...d,...p,stressShocks:shocks,horizonYears:Number(p.horizonYears??d.horizonYears)||d.horizonYears,reviewFrequencyMonths:Math.max(1,Math.round(Number(p.reviewFrequencyMonths??d.reviewFrequencyMonths)||d.reviewFrequencyMonths)),maxAssetWeightPct:Math.max(0,Number(p.maxAssetWeightPct??d.maxAssetWeightPct)||0),minCashPct:Math.max(0,Number(p.minCashPct??d.minCashPct)||0)};}
function governanceConfigured(){const p=state.governancePolicy||{};return Boolean(p.updatedAt||p.objective||p.principles||p.liquidityNote||p.restrictedAssets);}
function governanceDueItems(){const t=today();return state.decisionJournal.filter(x=>x.status!=='CLOSED'&&x.reviewDate&&String(x.reviewDate).slice(0,10)<=t).sort((a,b)=>String(a.reviewDate).localeCompare(String(b.reviewDate)));}
function governanceUpcomingItems(){const t=today();return state.decisionJournal.filter(x=>x.status!=='CLOSED'&&x.reviewDate&&String(x.reviewDate).slice(0,10)>t).sort((a,b)=>String(a.reviewDate).localeCompare(String(b.reviewDate)));}
function topAssetWeight(){const total=state.assets.reduce((s,a)=>s+assetCurrentValue(a),0);if(!total||!state.assets.length)return {asset:null,weight:0};const rows=state.assets.map(a=>({asset:a,weight:assetCurrentValue(a)/total*100})).sort((a,b)=>b.weight-a.weight);return rows[0];}
function stressInputsFromPolicy(force=false){const grid=$('stressShockGrid');if(!grid)return;const classes=(state.summary?.allocation||[]).map(x=>x.className);if(!force&&grid.dataset.classes===classes.join('|')&&grid.children.length)return;grid.dataset.classes=classes.join('|');const shocks=state.governancePolicy?.stressShocks||{};grid.innerHTML=classes.length?classes.map(c=>`<label>${escapeHtml(c)}<div class="percent-input"><input data-stress-class="${escapeHtml(c)}" inputmode="decimal" value="${number.format(Number(shocks[c])||0)}"><span>%</span></div></label>`).join(''):'<div class="empty-state"><strong>Sem alocação disponível.</strong><p>Cadastre ativos para montar um cenário por classe.</p></div>';}
function readStressShocks(){const out={};document.querySelectorAll('[data-stress-class]').forEach(input=>{const v=parsePtNumber(input.value);out[input.dataset.stressClass]=Number.isFinite(v)?v:0;});return out;}
function computeStress(shocks){const allocation=state.summary?.allocation||[],total=Number(state.summary?.currentValue)||allocation.reduce((s,x)=>s+(Number(x.value)||0),0);let impact=0;const rows=allocation.map(x=>{const shock=Number(shocks?.[x.className])||0,value=Number(x.value)||0,delta=value*shock/100;impact+=delta;return {className:x.className,value,shock,delta,after:value+delta};});return {rows,total,impact,after:total+impact,pct:total?impact/total*100:0};}
function renderStressResult(result){const el=$('stressResult');if(!el)return;if(!result){el.innerHTML='<div class="stress-empty">Defina os choques acima e calcule o cenário.</div>';return;}el.innerHTML=`<div class="stress-summary"><div><span>Patrimônio atual</span><strong>${money.format(result.total)}</strong></div><div><span>Impacto hipotético</span><strong class="${result.impact>=0?'positive':'negative'}">${money.format(result.impact)} · ${fmtPct(result.pct)}</strong></div><div><span>Após o cenário</span><strong>${money.format(result.after)}</strong></div></div><div class="stress-breakdown">${result.rows.map(r=>`<div class="stress-row"><span>${escapeHtml(r.className)}</span><small>${fmtPct(r.shock)}</small><strong class="${r.delta>=0?'positive':'negative'}">${money.format(r.delta)}</strong></div>`).join('')}</div>`;}
function calculateStressTest(){state.stressResult=computeStress(readStressShocks());renderStressResult(state.stressResult);}
