  if(!$('governanceMandate'))return;state.governancePolicy=normalizeGovernancePolicy(state.governancePolicy||{});const p=state.governancePolicy,configured=governanceConfigured(),due=governanceDueItems(),upcoming=governanceUpcomingItems(),top=topAssetWeight(),cash=Number((state.summary?.allocation||[]).find(x=>x.className==='Caixa')?.pct)||0,savedStress=computeStress(p.stressShocks||{});
  $('governanceMandateStatus').textContent=configured?'registrado':'pendente';$('governanceDueCount').textContent=String(due.length);$('governanceTopWeight').textContent=fmtPct(top.weight);$('governanceStressImpact').textContent=fmtPct(savedStress.pct);$('governanceStressImpact').className=savedStress.pct>=0?'positive':'negative';
