function normalizeRules(rows=[]){
  const byKey=Object.fromEntries((Array.isArray(rows)?rows:[]).map(r=>[r.key,r]));
  return RULE_DEFS.map(def=>({key:def.key,enabled:byKey[def.key]?.enabled!==false,threshold:byKey[def.key]?.threshold??def.threshold,updatedAt:byKey[def.key]?.updatedAt||null}));
}
function getRule(key){return state.automaticRules.find(r=>r.key===key)||normalizeRules([]).find(r=>r.key===key);}
function assetCurrentValue(a){const v=Number(a.currentValue);return Number.isFinite(v)&&v>=0?v:(Number(a.quantity)||0)*effectiveAssetPrice(a);}
function currentMonthKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}
function evaluateRuleSignals(){
  if(!state.automaticRules.length)state.automaticRules=normalizeRules([]);
  const signals=[];
  const enabled=(k)=>getRule(k)?.enabled!==false;
  const add=(key,message,detail='')=>{const def=RULE_DEFS.find(x=>x.key===key);signals.push({key,title:def?.title||key,message,detail,fingerprint:`${new Date().toISOString().slice(0,10)}:${key}:${message}`});};
  if(enabled('allocation_tolerance')){
    const limit=Math.max(0,Number(getRule('allocation_tolerance')?.threshold)||0), rows=strategyRows().filter(x=>Math.abs(x.diff)>limit);
    if(rows.length){const x=[...rows].sort((a,b)=>Math.abs(b.diff)-Math.abs(a.diff))[0];add('allocation_tolerance',`${x.className} está ${Math.abs(x.diff).toFixed(2).replace('.',',')} p.p. fora da meta.`,`${rows.length} classe(s) além de ±${number.format(limit)}%.`);}
  }
  if(enabled('asset_weight')){
    const total=state.assets.reduce((s,a)=>s+assetCurrentValue(a),0),limit=Math.max(0,Number(getRule('asset_weight')?.threshold)||0);
    const rows=total?state.assets.map(a=>({a,w:assetCurrentValue(a)/total*100})).filter(x=>x.w>limit).sort((a,b)=>b.w-a.w):[];
    if(rows.length)add('asset_weight',`${rows[0].a.symbol} representa ${fmtPct(rows[0].w)} da carteira.`,`${rows.length} ativo(s) acima do limite de ${fmtPct(limit)}.`);
  }
  if(enabled('stale_quote')){
    const hours=Math.max(1,Number(getRule('stale_quote')?.threshold)||6),cut=Date.now()-hours*3600000;
    const rows=state.assets.filter(a=>a.autoQuote&&(!a.marketPriceAt||new Date(a.marketPriceAt).getTime()<cut));
    if(rows.length)add('stale_quote',`${rows.length} cotação(ões) precisam de atualização.`,`Limite configurado: ${number.format(hours)} h.`);
  }
  if(enabled('price_target')){
    const rows=state.watchlist.filter(x=>x.alertTriggered);
    if(rows.length)add('price_target',`${rows.length} ativo(s) da watchlist atingiram a faixa de preço definida.`,rows.slice(0,3).map(x=>x.symbol).join(', '));
  }
  if(enabled('monthly_checkin')){
    const day=Math.min(28,Math.max(1,Number(getRule('monthly_checkin')?.threshold)||10)),month=currentMonthKey();
    if(new Date().getDate()>=day&&!state.financeCheckins.some(x=>x.month===month))add('monthly_checkin',`O check-in de ${month.split('-').reverse().join('/')} ainda não foi preenchido.`,`Regra ativa a partir do dia ${day}.`);
  }
  if(enabled('goal_overdue')){
    const t=today(), rows=state.financialGoals.filter(g=>g.targetDate&&String(g.targetDate).slice(0,10)<t&&(Number(g.currentAmount)||0)<(Number(g.targetAmount)||0));
    if(rows.length)add('goal_overdue',`${rows.length} meta(s) pessoal(is) passaram do prazo cadastrado.`,rows.slice(0,3).map(x=>x.title).join(', '));
  }
  if(enabled('data_incomplete')){
    const targetTotal=state.targets.reduce((s,x)=>s+(Number(x.targetPct)||0),0),noAvg=state.assets.filter(a=>(Number(a.averagePrice)||0)<=0).length,noPrice=state.assets.filter(a=>effectiveAssetPrice(a)<=0).length;
    const issues=[];if(state.targets.length&&Math.abs(targetTotal-100)>.05)issues.push(`metas somam ${fmtPct(targetTotal)}`);if(noAvg)issues.push(`${noAvg} posição(ões) sem preço médio`);if(noPrice)issues.push(`${noPrice} posição(ões) sem preço utilizável`);
    if(issues.length)add('data_incomplete','Há dados incompletos que reduzem a qualidade das análises.',issues.join(' · '));
  }
  if(enabled('governance_review')){
    const rows=governanceDueItems();if(rows.length)add('governance_review',`${rows.length} registro(s) do diário chegaram à data de revisão.`,rows.slice(0,3).map(x=>x.symbol||x.title).join(', '));
  }
  state.currentRuleSignals=signals;return signals;
}
function dataHealthSnapshot(){
  const targetTotal=state.targets.reduce((s,x)=>s+(Number(x.targetPct)||0),0),missingQuotes=state.assets.filter(a=>a.autoQuote&&a.marketPrice==null).length,noAvg=state.assets.filter(a=>(Number(a.averagePrice)||0)<=0).length;
  const stale=state.assets.filter(a=>a.autoQuote&&a.marketPriceAt&&(Date.now()-new Date(a.marketPriceAt).getTime())>6*3600000).length;
  return [
    {ok:!state.targets.length||Math.abs(targetTotal-100)<.05,label:'Metas de alocação',detail:state.targets.length?`Soma: ${fmtPct(targetTotal)}`:'Ainda não configuradas'},
    {ok:missingQuotes===0,label:'Cobertura de cotações',detail:missingQuotes?`${missingQuotes} ativo(s) sem preço automático`:'Cobertura atual sem falhas'},
    {ok:noAvg===0,label:'Preço médio',detail:noAvg?`${noAvg} posição(ões) pendentes`:'Preços médios preenchidos'},
    {ok:stale===0,label:'Frescura das cotações',detail:stale?`${stale} cotação(ões) com mais de 6 h`:'Sem cotações antigas > 6 h'}
  ];
}
function upcomingDecisionEvents(){
  const now=new Date();now.setHours(0,0,0,0);const end=new Date(now);end.setDate(end.getDate()+30);const rows=[];
  for(const e of state.calendarEvents){const d=new Date(`${String(e.eventDate||'').slice(0,10)}T00:00:00`);if(d>=now&&d<=end)rows.push({date:e.eventDate,title:e.title,kind:'Agenda'});}
  for(const e of (state.agenda?.dividends||[])){const d=new Date(`${String(e.paymentDate||'').slice(0,10)}T00:00:00`);if(d>=now&&d<=end)rows.push({date:e.paymentDate,title:`${e.symbol} · ${e.label||'Provento anunciado'}`,kind:'Provento'});}
  for(const g of state.financialGoals){if(!g.targetDate)continue;const d=new Date(`${String(g.targetDate).slice(0,10)}T00:00:00`);if(d>=now&&d<=end)rows.push({date:g.targetDate,title:g.title,kind:'Meta'});}
  for(const j of state.decisionJournal){if(j.status==='CLOSED'||!j.reviewDate)continue;const d=new Date(`${String(j.reviewDate).slice(0,10)}T00:00:00`);if(d>=now&&d<=end)rows.push({date:j.reviewDate,title:j.symbol?`${j.symbol} · ${j.title}`:j.title,kind:'Revisão'});}
  return rows.sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(0,6);
}
function renderDecisionCenter(){
  renderDecisionBase();
  const rows=strategyRows(),under=rows.filter(x=>x.status==='under').sort((a,b)=>a.diff-b.diff),outside=rows.filter(x=>x.status!=='inside');
  const stale=state.assets.filter(a=>a.autoQuote&&(!a.marketPriceAt||(Date.now()-new Date(a.marketPriceAt).getTime())>6*3600000)).length;
  const health=dataHealthSnapshot(),missing=health.filter(x=>!x.ok).length,signals=evaluateRuleSignals(),watchAlerts=state.watchlist.filter(x=>x.alertTriggered||x.changeAlertTriggered).length;
  if($('decisionOutsideCount'))$('decisionOutsideCount').textContent=String(outside.length);if($('decisionStaleCount'))$('decisionStaleCount').textContent=String(stale);if($('decisionMissingCount'))$('decisionMissingCount').textContent=String(missing);if($('decisionAlertCount'))$('decisionAlertCount').textContent=String(signals.length+watchAlerts);
  const focus=under[0];
  if($('decisionFocusBadge'))$('decisionFocusBadge').textContent=focus?'abaixo da meta':'dentro da faixa';
  if($('decisionFocus'))$('decisionFocus').innerHTML=focus?`<div class="focus-hero"><div><strong>${escapeHtml(focus.className)}</strong><span>${fmtPct(focus.current)} hoje · meta ${fmtPct(focus.target)}</span></div><div class="focus-gap"><strong class="negative">${fmtPct(focus.diff)}</strong><span>diferença</span></div></div><div class="focus-meter"><i style="width:${Math.max(4,Math.min(100,(focus.current/Math.max(focus.target,1))*100))}%"></i></div><p class="focus-copy">Entre as classes abaixo da faixa definida por você, esta é a maior distância atual. No simulador de aporte, ela tende a receber prioridade matemática enquanto o desvio persistir.</p>`:'<div class="empty-state"><strong>Nenhuma classe abaixo da faixa.</strong><p>As metas configuradas estão dentro da tolerância atual ou ainda não há dados suficientes.</p></div>';
  const events=upcomingDecisionEvents();if($('decisionEvents'))$('decisionEvents').innerHTML=events.length?events.map(e=>`<div class="executive-row"><i class="executive-dot"></i><div><strong>${escapeHtml(e.title)}</strong><small>${escapeHtml(e.kind)} · ${fmtDate(e.date)}</small></div><span>${fmtDate(e.date)}</span></div>`).join(''):'<div class="empty-state"><strong>Agenda livre nos próximos 30 dias.</strong><p>Eventos, metas e proventos anunciados aparecerão aqui.</p></div>';
  if($('decisionDataBadge'))$('decisionDataBadge').textContent=missing?`${missing} ponto${missing===1?'':'s'}`:'base consistente';if($('decisionDataHealth'))$('decisionDataHealth').innerHTML=health.map(x=>`<div class="executive-row"><i class="executive-dot ${x.ok?'good':'warn'}"></i><div><strong>${escapeHtml(x.label)}</strong><small>${escapeHtml(x.detail)}</small></div><span>${x.ok?'ok':'revisar'}</span></div>`).join('');
  if($('decisionRuleSignals'))$('decisionRuleSignals').innerHTML=signals.length?signals.slice(0,5).map(x=>`<div class="executive-row"><i class="executive-dot bad"></i><div><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml(x.message)}${x.detail?` · ${escapeHtml(x.detail)}`:''}</small></div><span>ativo</span></div>`).join(''):'<div class="empty-state"><strong>Nenhuma regra disparada agora.</strong><p>Os sinais são recalculados com base nos limites configurados.</p></div>';
}
function renderRules(){
  const grid=$('rulesGrid');if(!grid)return;if(!state.automaticRules.length)state.automaticRules=normalizeRules([]);const signals=evaluateRuleSignals();const activeKeys=new Set(signals.map(x=>x.key));
  grid.innerHTML=RULE_DEFS.map(def=>{const rule=getRule(def.key);return `<article class="rule-card"><div class="rule-head"><div><strong>${escapeHtml(def.title)}</strong><small>${escapeHtml(def.description)}</small></div><label class="rule-toggle" aria-label="Ativar ${escapeHtml(def.title)}"><input id="ruleEnabled-${def.key}" type="checkbox" ${rule.enabled!==false?'checked':''}><span></span></label></div>${def.hasThreshold?`<div class="rule-config"><label>Limite<input id="ruleThreshold-${def.key}" inputmode="decimal" value="${number.format(Number(rule.threshold??def.threshold)||0)}"></label><span class="rule-status ${activeKeys.has(def.key)?'triggered':''}">${activeKeys.has(def.key)?'disparada':'normal'}${def.unit?` · ${escapeHtml(def.unit)}`:''}</span></div>`:`<div class="rule-config"><span class="rule-status ${activeKeys.has(def.key)?'triggered':''}">${activeKeys.has(def.key)?'disparada agora':'sem sinal atual'}</span></div>`}</article>`}).join('');
  if($('ruleHistoryBadge'))$('ruleHistoryBadge').textContent=`${state.ruleHistory.length} evento${state.ruleHistory.length===1?'':'s'}`;
  if($('ruleHistory'))$('ruleHistory').innerHTML=state.ruleHistory.length?state.ruleHistory.slice(0,30).map(e=>`<div class="rule-history-row"><time>${fmtDateTime(e.createdAt)}</time><div><strong>${escapeHtml(e.title||RULE_DEFS.find(x=>x.key===e.key)?.title||e.key)}</strong><small>${escapeHtml(e.message||'')}</small></div><span>${escapeHtml(e.detail||'')}</span></div>`).join(''):'<div class="empty-state"><strong>Ainda não há histórico.</strong><p>Use “Reavaliar agora” para registrar os sinais ativos no momento.</p></div>';
}
async function saveAutomaticRules(){
  const rules=RULE_DEFS.map(def=>({key:def.key,enabled:Boolean($(`ruleEnabled-${def.key}`)?.checked),threshold:def.hasThreshold?Math.max(0,parsePtNumber($(`ruleThreshold-${def.key}`)?.value)||0):null}));
  const btn=$('saveRulesButton');setBusy(btn,true,'Salvando…');try{if(state.preview){state.automaticRules=normalizeRules(rules);savePreviewFinance();}else{const data=await api('/api/decision-rules',{method:'PUT',body:JSON.stringify({rules})});state.automaticRules=normalizeRules(data.rules||rules);}renderRules();renderDecisionCenter();toast('Regras automáticas salvas.');}catch(e){toast(e.message)}finally{setBusy(btn,false);}
}
async function evaluateAndRecordRules(){
  const signals=evaluateRuleSignals(),btn=$('evaluateRulesButton');if(btn)setBusy(btn,true,'Avaliando…');try{if(signals.length){if(state.preview){const known=new Set(state.ruleHistory.map(x=>x.fingerprint));const fresh=signals.filter(x=>!known.has(x.fingerprint)).map(x=>({...x,createdAt:new Date().toISOString()}));state.ruleHistory=[...fresh,...state.ruleHistory].slice(0,100);savePreviewFinance();}else{const data=await api('/api/decision-rules',{method:'POST',body:JSON.stringify({events:signals})});state.ruleHistory=data.history||state.ruleHistory;}}renderRules();renderDecisionCenter();toast(signals.length?`${signals.length} sinal(is) ativo(s) avaliados.`:'Nenhuma regra disparada no momento.');}catch(e){toast(e.message)}finally{if(btn)setBusy(btn,false);}
}
function reportPeriodLabel(type,month,year){if(type==='monthly'){const [y,m]=month.split('-');return new Date(Date.UTC(Number(y),Number(m)-1,1)).toLocaleDateString('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'});}return String(year);}
function reportTable(headers,rows){if(!rows.length)return '<div class="report-note">Nenhum registro encontrado para este recorte.</div>';return `<table class="report-table"><thead><tr>${headers.map(h=>`<th>${escapeHtml(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${escapeHtml(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function reportKpi(label,value,small=''){return `<div class="report-kpi"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small>${escapeHtml(small)}</small></div>`;}
function setupReportControls(){
  const month=$('reportMonth'),year=$('reportYear');if(!month||!year)return;const d=new Date();if(!month.value)month.value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
  const years=new Set([d.getFullYear(),...state.transactions.map(x=>Number(String(x.tradeDate||'').slice(0,4))),...state.income.map(x=>Number(String(x.paymentDate||'').slice(0,4))),...(state.performance?.points||[]).map(x=>Number(String(x.date||'').slice(0,4)))]);const vals=[...years].filter(Number.isFinite).sort((a,b)=>b-a);const selected=Number(year.value)||d.getFullYear();year.innerHTML=vals.map(y=>`<option value="${y}" ${y===selected?'selected':''}>${y}</option>`).join('');
}

function normalizeSecuritySettings(raw={}){const freq=['DAILY','WEEKLY','MONTHLY'].includes(String(raw.backupFrequency))?String(raw.backupFrequency):'WEEKLY';const mins=[5,15,30,60,120,240].includes(Number(raw.idleTimeoutMinutes))?Number(raw.idleTimeoutMinutes):30;return {idleEnabled:raw.idleEnabled!==false,idleTimeoutMinutes:mins,backgroundLogout:raw.backgroundLogout!==false,autoBackupEnabled:raw.autoBackupEnabled!==false,backupFrequency:freq,updatedAt:raw.updatedAt||null};}
function securityPreviewKey(){return `pi-r19-security-${state.user?.theme||document.body.dataset.theme||'camile'}`;}
function loadPreviewSecurity(){try{return normalizeSecuritySettings(JSON.parse(localStorage.getItem(securityPreviewKey())||'{}'));}catch{return normalizeSecuritySettings({});}}
function savePreviewSecurity(){try{localStorage.setItem(securityPreviewKey(),JSON.stringify(state.securitySettings));}catch{}}
function deviceLabel(ua=''){const s=String(ua||'');if(!s)return'Dispositivo';if(/iphone|ipad/i.test(s))return'iPhone / iPad';if(/android/i.test(s))return'Android';if(/windows/i.test(s))return'Windows';if(/macintosh|mac os/i.test(s))return'Mac';return s.slice(0,42);}
function eventLabel(type){return ({LOGIN_SUCCESS:'Login realizado',LOGIN_FAILED:'Tentativa de login',LOGOUT:'Sessão encerrada',PASSWORD_CHANGED:'Senha alterada',BACKUP_CREATED:'Backup criado',SESSIONS_REVOKED:'Outras sessões encerradas',SECURITY_SETTINGS_UPDATED:'Política de segurança atualizada'}[type]||String(type||'Evento').replaceAll('_',' ').toLowerCase());}
function eventIcon(type){return ({LOGIN_SUCCESS:'↳',LOGIN_FAILED:'!',LOGOUT:'↪',PASSWORD_CHANGED:'✦',BACKUP_CREATED:'◇',SESSIONS_REVOKED:'×',SECURITY_SETTINGS_UPDATED:'⌾'}[type]||'·');}
function formatBytes(v){const n=Number(v)||0;if(n<1024)return`${n} B`;if(n<1048576)return`${(n/1024).toFixed(1)} KB`;return`${(n/1048576).toFixed(1)} MB`;}
function renderSecurityCenter(){if(!$('securitySection'))return;const cfg=normalizeSecuritySettings(state.securitySettings);$('securityIdleEnabled').checked=cfg.idleEnabled;$('securityIdleMinutes').value=String(cfg.idleTimeoutMinutes);$('securityBackgroundLogout').checked=cfg.backgroundLogout;$('securityAutoBackup').checked=cfg.autoBackupEnabled;$('securityBackupFrequency').value=cfg.backupFrequency;const protections=[state.securityReadiness?.httpOnly,state.securityReadiness?.sameSite,state.securityReadiness?.rateLimit,state.securityReadiness?.dataIsolation].filter(Boolean).length;$('securityProtectionCount').textContent=`${protections}/4`;$('securityProtectionDetail').textContent=protections===4?'proteções essenciais ativas':'revise a preparação do ambiente';$('securitySessionCount').textContent=String(state.securitySessions.length||1);const latest=state.vaultBackups[0];$('securityLastBackup').textContent=latest?fmtDate(latest.createdAt):'Nenhum';$('securityLastBackupDetail').textContent=latest?`${formatBytes(latest.sizeBytes)} · ${latest.label||'versão do cofre'}`:'crie a primeira versão';$('securityPolicyBadge').textContent=cfg.idleEnabled?`${cfg.idleTimeoutMinutes} min`:'sem expiração local';$('backupCountBadge').textContent=`${state.vaultBackups.length} ${state.vaultBackups.length===1?'versão':'versões'}`;
  $('securitySessions').innerHTML=state.securitySessions.length?state.securitySessions.map(x=>`<div class="r19-session-row"><span class="r19-session-icon">${x.current?'●':'○'}</span><div><strong>${escapeHtml(deviceLabel(x.userAgent))}</strong><small>Iniciada ${fmtDateTime(x.createdAt)} · vista ${fmtDateTime(x.lastSeenAt||x.createdAt)}</small></div>${x.current?'<span class="r19-current-session">sessão atual</span>':`<span class="r19-current-session">expira ${fmtDate(x.expiresAt)}</span>`}</div>`).join(''):'<p class="empty-text">Nenhuma sessão adicional encontrada.</p>';
  $('vaultBackupList').innerHTML=state.vaultBackups.length?state.vaultBackups.map(x=>`<div class="r19-backup-row"><div><strong>${escapeHtml(x.label||'Backup da carteira')}</strong><small>${fmtDateTime(x.createdAt)} · versão #${x.id}</small></div><span class="r19-backup-size">${formatBytes(x.sizeBytes)}</span><button class="r19-backup-download" type="button" data-backup-id="${x.id}">↓ JSON</button></div>`).join(''):'<p class="empty-text">O cofre ainda não possui versões. Crie um backup para registrar a primeira.</p>';
  const checks=[['https','HTTPS no ambiente publicado','Protege o tráfego entre navegador e aplicação.'],['httpOnly','Cookie HttpOnly','O token de sessão não fica disponível ao JavaScript da página.'],['sameSite','SameSite estrito','Reduz o risco de envio do cookie em requisições de outros sites.'],['rateLimit','Proteção de tentativas','Bloqueio temporário após repetidas senhas incorretas.'],['dataIsolation','Dados isolados por usuário','Consultas sempre partem do usuário autenticado.'],['cloudDatabase','Base persistente','Dados e versões do cofre ficam persistidos no ambiente publicado.']];$('securityReadiness').innerHTML=checks.map(([k,t,d])=>`<div class="r19-readiness-row ${state.securityReadiness?.[k]?'':'warn'}"><span class="r19-readiness-dot">${state.securityReadiness?.[k]?'✓':'!'}</span><div><strong>${t}</strong><small>${d}</small></div></div>`).join('');
  $('securityAudit').innerHTML=state.securityAudit.length?state.securityAudit.slice(0,20).map(x=>`<div class="r19-audit-row"><span class="r19-audit-time">${fmtDateTime(x.createdAt)}</span><span class="r19-audit-icon">${eventIcon(x.eventType)}</span><div><strong>${eventLabel(x.eventType)}</strong><small>${escapeHtml(x.detail||deviceLabel(x.userAgent)||'')}</small></div></div>`).join(''):'<p class="empty-text">Os próximos eventos de segurança aparecerão aqui.</p>';
}
async function saveSecuritySettings(){const btn=$('saveSecuritySettings');const payload={idleEnabled:$('securityIdleEnabled').checked,idleTimeoutMinutes:Number($('securityIdleMinutes').value)||30,backgroundLogout:$('securityBackgroundLogout').checked,autoBackupEnabled:$('securityAutoBackup').checked,backupFrequency:$('securityBackupFrequency').value};setBusy(btn,true,'Salvando…');try{if(state.preview){state.securitySettings=normalizeSecuritySettings(payload);savePreviewSecurity();state.securityAudit.unshift({eventType:'SECURITY_SETTINGS_UPDATED',createdAt:new Date().toISOString(),userAgent:'Prévia local',detail:'Preferências salvas neste navegador'});}else{const data=await api('/api/security',{method:'PUT',body:JSON.stringify(payload)});state.securitySettings=normalizeSecuritySettings(data.settings||payload);if(Array.isArray(data.audit))state.securityAudit=data.audit;}configureSessionGuard();renderSecurityCenter();toast('Política de segurança salva.');}catch(e){toast(e.message);}finally{setBusy(btn,false);}}
function previewBackupPayload(){return {format:'pi-vault',version:23.1,generatedAt:new Date().toISOString(),user:{displayName:state.user?.displayName,theme:state.user?.theme},summary:state.summary,assets:state.assets,targets:state.targets,transactions:state.transactions,income:state.income,watchlist:state.watchlist,planningSettings:state.planningSettings,personalFinance:state.personalFinance,financialGoals:state.financialGoals,monthlyClosings:state.monthlyClosings,governance:{policy:state.governancePolicy,journal:state.decisionJournal},personalization:state.personalization,automationSettings:state.automationSettings,securitySettings:state.securitySettings,financialBaselines:state.financialBaselines};}
async function createVaultBackup({silent=false,automatic=false}={}){const btn=$('createVaultBackup');if(!silent)setBusy(btn,true,'Criando…');try{if(state.preview){const payload=previewBackupPayload(),raw=JSON.stringify(payload);const item={id:Date.now(),label:automatic?'Backup automático':'Backup manual',sizeBytes:new Blob([raw]).size,createdAt:new Date().toISOString()};state.vaultBackups.unshift(item);state.vaultBackups=state.vaultBackups.slice(0,10);state.securityAudit.unshift({eventType:'BACKUP_CREATED',createdAt:item.createdAt,userAgent:'Prévia local',detail:item.label});}else{const data=await api('/api/backups',{method:'POST',body:JSON.stringify({label:automatic?'Backup automático':'Backup manual'})});state.vaultBackups=Array.isArray(data.backups)?data.backups:state.vaultBackups;if(data.audit)state.securityAudit=data.audit;}renderSecurityCenter();if(!silent)toast('Backup criado no cofre.');return true;}catch(e){if(!silent)toast(e.message);return false;}finally{if(!silent)setBusy(btn,false);}}
async function downloadVaultBackup(id){try{let payload;if(state.preview){payload=previewBackupPayload();payload.backupId=id;}else{payload=await api(`/api/backups?id=${encodeURIComponent(id)}`);}downloadTextFile(`plataforma-investimentos-vault-${id}.json`,JSON.stringify(payload.snapshot||payload,null,2),'application/json;charset=utf-8');toast('Backup JSON preparado.');}catch(e){toast(e.message);}}
async function logoutOtherSessions(){const btn=$('logoutOtherSessions');setBusy(btn,true,'Encerrando…');try{if(state.preview){state.securitySessions=state.securitySessions.filter(x=>x.current);state.securityAudit.unshift({eventType:'SESSIONS_REVOKED',createdAt:new Date().toISOString(),userAgent:'Prévia local',detail:'Outras sessões demonstrativas encerradas'});}else{const data=await api('/api/security',{method:'POST',body:JSON.stringify({action:'logout_other_sessions'})});state.securitySessions=data.sessions||[];state.securityAudit=data.audit||state.securityAudit;}renderSecurityCenter();toast('Outras sessões encerradas.');}catch(e){toast(e.message);}finally{setBusy(btn,false);}}
function configureSessionGuard(){clearTimeout(state.inactivityTimer);state.inactivityTimer=null;if(!state.user||state.preview&&state.privacyLocked)return;if(state.securitySettings?.idleEnabled){const ms=Math.max(5,Number(state.securitySettings.idleTimeoutMinutes)||30)*60000;state.inactivityTimer=setTimeout(()=>securityAutoLogout('Sessão encerrada por inatividade.'),ms);}}
function noteSecurityActivity(){if(state.privacyLocked)return;configureSessionGuard();}
async function securityAutoLogout(message='Sessão encerrada por segurança.'){if(!state.user)return;stopLiveTimers();if(!state.preview){try{await api('/api/logout',{method:'POST',body:'{}'});}catch{}}showLogin();$('loginError').textContent=message;}
function lockPrivacyScreen(){if(!state.user)return;state.privacyLocked=true;clearTimeout(state.inactivityTimer);$('privacyUnlockPassword').value='';$('privacyLockError').textContent='';$('privacyLock').hidden=false;$('privacyPasswordLabel').hidden=state.preview;$('privacyLockCopy').textContent=state.preview?'Prévia local: use o botão abaixo para voltar à plataforma.':'Digite a senha deste usuário para voltar à plataforma.';setTimeout(()=>state.preview?$('privacyUnlockButton').focus():$('privacyUnlockPassword').focus(),40);}
async function unlockPrivacyScreen(){const btn=$('privacyUnlockButton');$('privacyLockError').textContent='';if(state.preview){state.privacyLocked=false;$('privacyLock').hidden=true;configureSessionGuard();return;}const password=$('privacyUnlockPassword').value;if(!password){$('privacyLockError').textContent='Digite sua senha.';return;}setBusy(btn,true,'Verificando…');try{await api('/api/security',{method:'POST',body:JSON.stringify({action:'verify_password',password})});state.privacyLocked=false;$('privacyLock').hidden=true;configureSessionGuard();}catch(e){$('privacyLockError').textContent=e.message;}finally{setBusy(btn,false);}}
async function maybeCreateScheduledBackup(){const cfg=state.securitySettings;if(!cfg?.autoBackupEnabled||!state.user)return;const last=state.vaultBackups[0]?.createdAt?new Date(state.vaultBackups[0].createdAt).getTime():0;const now=Date.now();const span=cfg.backupFrequency==='DAILY'?86400000:cfg.backupFrequency==='MONTHLY'?30*86400000:7*86400000;if(!last||now-last>=span)await createVaultBackup({silent:true,automatic:true});}
function handleVisibilitySecurity(){if(document.hidden){state.backgroundHiddenAt=Date.now();return;}if(state.backgroundHiddenAt&&state.securitySettings?.backgroundLogout&&state.securitySettings?.idleEnabled){const elapsed=Date.now()-state.backgroundHiddenAt;const limit=Math.max(5,Number(state.securitySettings.idleTimeoutMinutes)||30)*60000;if(elapsed>=limit)securityAutoLogout('Sessão encerrada após período prolongado fora da aba.');}state.backgroundHiddenAt=0;noteSecurityActivity();}


function r20CurrentMonth(){return new Date().toISOString().slice(0,7);}
